import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_depth,
    int in_height,
    int in_width,
    int kernel_d,
    int kernel_h,
    int kernel_w,
    int stride_d,
    int stride_h,
    int stride_w,
    int padding_d,
    int padding_h,
    int padding_w,
    int output_padding_d,
    int output_padding_h,
    int output_padding_w,
    int groups,
    float* output,
    int out_depth,
    int out_height,
    int out_width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    if (idx >= total_elements) return;

    int n = idx / (out_channels * out_depth * out_height * out_width);
    int remainder = idx % (out_channels * out_depth * out_height * out_width);
    int oc = remainder / (out_depth * out_height * out_width);
    remainder %= (out_depth * out_height * out_width);
    int od = remainder / (out_height * out_width);
    remainder %= (out_height * out_width);
    int oh = remainder / out_width;
    int ow = remainder % out_width;

    int out_channels_per_group = out_channels / groups;
    int g = oc / out_channels_per_group;
    int oc_in_group = oc % out_channels_per_group;

    int in_channels_per_group = in_channels / groups;
    int input_start_channel = g * in_channels_per_group;

    float sum = 0.0f;

    for (int kd = 0; kd < kernel_d; ++kd) {
        for (int kh = 0; kh < kernel_h; ++kh) {
            for (int kw = 0; kw < kernel_w; ++kw) {
                int id = (od - kd + padding_d) / stride_d;
                int ih = (oh - kh + padding_h) / stride_h;
                int iw = (ow - kw + padding_w) / stride_w;

                if ((od - kd + padding_d) %% stride_d != 0) continue;
                if ((oh - kh + padding_h) %% stride_h != 0) continue;
                if ((ow - kw + padding_w) %% stride_w != 0) continue;
                if (id < 0 || id >= in_depth) continue;
                if (ih < 0 || ih >= in_height) continue;
                if (iw < 0 || iw >= in_width) continue;

                for (int ic = 0; ic < in_channels_per_group; ++ic) {
                    int input_channel = input_start_channel + ic;
                    int input_idx = n * in_channels * in_depth * in_height * in_width +
                                    input_channel * in_depth * in_height * in_width +
                                    id * in_height * in_width +
                                    ih * in_width +
                                    iw;

                    int weight_idx = input_channel * out_channels_per_group * kernel_d * kernel_h * kernel_w +
                                     oc_in_group * kernel_d * kernel_h * kernel_w +
                                     kd * kernel_h * kernel_w +
                                     kh * kernel_w +
                                     kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias != nullptr) sum += bias[oc];
    output[idx] = sum;
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_d,
    int kernel_h,
    int kernel_w,
    int stride_d,
    int stride_h,
    int stride_w,
    int padding_d,
    int padding_h,
    int padding_w,
    int output_padding_d,
    int output_padding_h,
    int output_padding_w,
    int groups
) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_depth = input.size(2);
    int in_height = input.size(3);
    int in_width = input.size(4);

    int out_depth = (in_depth - 1) * stride_d - 2 * padding_d + kernel_d + output_padding_d;
    int out_height = (in_height - 1) * stride_h - 2 * padding_h + kernel_h + output_padding_h;
    int out_width = (in_width - 1) * stride_w - 2 * padding_w + kernel_w + output_padding_w;

    auto output = torch::zeros({batch_size, weight.size(1)*groups, out_depth, out_height, out_width}, input.options());
    bool has_bias = bias.defined() && bias.numel() > 0;

    int total_elements = output.numel();
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<grid_size, block_size>>>(
        input.contiguous().data_ptr<float>(),
        weight.contiguous().data_ptr<float>(),
        has_bias ? bias.contiguous().data_ptr<float>() : nullptr,
        batch_size,
        in_channels,
        output.size(1),
        in_depth,
        in_height,
        in_width,
        kernel_d,
        kernel_h,
        kernel_w,
        stride_d,
        stride_h,
        stride_w,
        padding_d,
        padding_h,
        padding_w,
        output_padding_d,
        output_padding_h,
        output_padding_w,
        groups,
        output.data_ptr<float>(),
        out_depth,
        out_height,
        out_width
    );

    return output;
}
"""

conv_transpose3d_cpp_source = """
torch::Tensor conv_transpose3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_d,
    int kernel_h,
    int kernel_w,
    int stride_d,
    int stride_h,
    int stride_w,
    int padding_d,
    int padding_h,
    int padding_w,
    int output_padding_d,
    int output_padding_h,
    int output_padding_w,
    int groups
);
"""

conv_transpose3d_ext = load_inline(
    name='conv_transpose3d',
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=['conv_transpose3d_forward'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self.weight = nn.Parameter(torch.empty(
            in_channels,
            out_channels // groups,
            kernel_size[0],
            kernel_size[1],
            kernel_size[2]
        ))
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            nn.init.zeros_(self.bias)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv_transpose3d_ext.conv_transpose3d_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.Tensor(),
            self.kernel_size[0],
            self.kernel_size[1],
            self.kernel_size[2],
            self.stride[0],
            self.stride[1],
            self.stride[2],
            self.padding[0],
            self.padding[1],
            self.padding[2],
            self.output_padding[0],
            self.output_padding[1],
            self.output_padding[2],
            self.groups
        )
